import net.sf.jsqlparser.JSQLParserException;
import net.sf.jsqlparser.parser.CCJSqlParserUtil;
import net.sf.jsqlparser.statement.select.Select;
import net.sf.jsqlparser.statement.Statement;

public String convertToPageSql(String sql, Integer offset, Integer limit) {
    try {
        Statement stmt = CCJSqlParserUtil.parse(sql);
        if (!(stmt instanceof Select)) {
            throw new PageException("分页语句必须是Select查询!");
        }

        Select select = (Select) stmt;
        String originalSql = select.toString();

        if (offset == null && limit == null) {
            return originalSql;
        }

        String pageSql = originalSql;

        if (offset != null) {
            pageSql = "SELECT * FROM (SELECT ROW_NUMBER() OVER(ORDER BY CURRENT_TIMESTAMP) AS RN, " +
                      "inner_query.* FROM (" + originalSql + ") AS inner_query) AS outer_query " +
                      "WHERE RN > " + offset;
        }

        if (limit != null) {
            if (pageSql.toLowerCase().contains("order by")) {
                pageSql = "SELECT * FROM (" + pageSql + ") AS page_table_alias LIMIT " + limit;
            } else {
                pageSql = pageSql + " LIMIT " + limit;
            }
        }

        return pageSql;
    } catch (JSQLParserException e) {
        throw new PageException("不支持该SQL转换为分页查询!", e);
    }
}

