import net.sf.jsqlparser.JSQLParserException;
import net.sf.jsqlparser.parser.CCJSqlParserUtil;
import net.sf.jsqlparser.statement.select.Select;
import net.sf.jsqlparser.statement.SelectBody;
import net.sf.jsqlparser.statement.select.PlainSelect;
import net.sf.jsqlparser.statement.select.SetOperationList;
import net.sf.jsqlparser.statement.Statement;

public String convertToPageSql(String sql, Integer offset, Integer limit) {
    try {
        Statement stmt = CCJSqlParserUtil.parse(sql);
        if (!(stmt instanceof Select)) {
            throw new PageException("分页语句必须是Select查询!");
        }

        Select select = (Select) stmt;
        SelectBody selectBody = select.getSelectBody();

        if (offset == null) {
            offset = 0;
        }

        if (limit != null) {
            if (selectBody instanceof PlainSelect) {
                PlainSelect plainSelect = (PlainSelect) selectBody;
                plainSelect.setLimit(limit);
            } else if (selectBody instanceof SetOperationList) {
                SetOperationList setOperationList = (SetOperationList) selectBody;
                List<PlainSelect> plainSelects = setOperationList.getPlainSelects();
                if (plainSelects.size() > 0) {
                    plainSelects.get(0).setLimit(limit);
                }
            }
        }

        if (offset > 0) {
            String originalSql = select.toString();
            return "SELECT * FROM (SELECT ROW_NUMBER() OVER(ORDER BY (SELECT 1)) AS rn, inner_query.* FROM (" +
                   originalSql + ") AS inner_query) AS outer_query WHERE rn > " + offset;
        }

        return select.toString();
    } catch (JSQLParserException e) {
        throw new PageException("不支持该SQL转换为分页查询!", e);
    }
}

